SOURCE_RETAINER = "def retain_stage(pins):\n    directory = ROOT / ('android-cli-stage-' + GETTER['stageId'])\n    for name, item in pins.items():\n        path = directory / name if name in ('intent.json', 'receipt.json') else directory / 'tree' / name\n        fresh, leaf = parent_fds(path)\n        chain = []\n        untransferred = {entry['fd'] for entry in fresh}\n        fd = None\n        prefix = pathlib.Path('/')\n        try:\n            for number, entry in enumerate(fresh):\n                if number:\n                    prefix /= path.parts[number]\n                key = str(prefix)\n                if key in parent_cache:\n                    cached = parent_cache[key]\n                    if cached['pin'] != entry['pin'] or fp(os.fstat(cached['fd'])) != entry['pin']:\n                        raise ValueError('stage_generation_changed')\n                    os.close(entry['fd'])\n                    untransferred.remove(entry['fd'])\n                    chain.append(cached)\n                else:\n                    parent_cache[key] = entry\n                    untransferred.remove(entry['fd'])\n                    chain.append(entry)\n            guard_parents(chain)\n            fd = os.open(leaf, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=chain[-1]['fd'])\n            if fp(os.fstat(fd)) != item['generation'] or fp(os.stat(leaf, dir_fd=chain[-1]['fd'], follow_symlinks=False)) != item['generation']:\n                raise ValueError('stage_generation_changed')\n            held.append((chain, leaf, fd, item['generation']))\n            fd = None\n        finally:\n            if fd is not None:\n                os.close(fd)\n            for unused in untransferred:\n                os.close(unused)\n    if len(held) != 155:\n        raise ValueError('stage_inventory_changed')\ndef held_guard():\n    for chain, name, fd, generation in held:\n        guard_parents(chain)\n        if fp(os.fstat(fd)) != generation or fp(os.stat(name, dir_fd=chain[-1]['fd'], follow_symlinks=False)) != generation:\n            raise ValueError('stage_generation_changed')\n"
