OLD_COPIED_INPUT_SOURCE = "def recipe_file_copy(source_fd, destination_fd, name, expected):\n    before = fp(os.fstat(source_fd))\n    if before[2] != expected['size'] or not stat.S_ISREG(before[5]) or before[8] != 1:\n        raise ValueError('recipe_source_changed')\n    fd = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 384, dir_fd=destination_fd)\n    try:\n        offset = 0\n        digest = hashlib.sha256()\n        while offset < expected['size']:\n            if time.monotonic() >= overall_deadline:\n                raise ValueError('recipe_timeout')\n            raw = os.pread(source_fd, min(524288, expected['size'] - offset), offset)\n            if not raw:\n                raise ValueError('recipe_source_changed')\n            digest.update(raw)\n            cursor = 0\n            while cursor < len(raw):\n                cursor += os.write(fd, raw[cursor:])\n            offset += len(raw)\n        if os.pread(source_fd, 1, offset) or fp(os.fstat(source_fd)) != before or digest.hexdigest() != expected['sha256']:\n            raise ValueError('recipe_source_changed')\n        os.fchmod(fd, expected['mode'])\n        os.fsync(fd)\n    finally:\n        os.close(fd)\ndef recipe_walk(root, hold):\n    chain, leaf = parent_fds(root)\n    guard_parents(chain)\n    rows = {}\n    directories = {}\n    files = {}\n    transferred = False\n    try:\n        directories['.'] = os.open(leaf, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=chain[-1]['fd'])\n        queue = ['.']\n        while queue:\n            relative = queue.pop(0)\n            fd = directories[relative]\n            before = fp(os.fstat(fd))\n            if not stat.S_ISDIR(before[5]) or before[6:8] != [1000, 1000] or (not before[5] & 64):\n                raise ValueError('recipe_tree_shape')\n            names = sorted(os.listdir(fd))\n            if len(names) > 1024 or len(rows) > 1024:\n                raise ValueError('recipe_tree_limit')\n            rows[relative] = {'type': 'directory', 'generation': before, 'names': names}\n            for name in names:\n                path = name if relative == '.' else relative + '/' + name\n                info = os.stat(name, dir_fd=fd, follow_symlinks=False)\n                pin = fp(info)\n                if pin[6:8] != [1000, 1000]:\n                    raise ValueError('recipe_tree_shape')\n                if stat.S_ISDIR(info.st_mode):\n                    child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=fd)\n                    if fp(os.fstat(child)) != pin:\n                        os.close(child)\n                        raise ValueError('recipe_tree_changed')\n                    directories[path] = child\n                    queue.append(path)\n                elif stat.S_ISREG(info.st_mode) and info.st_nlink == 1:\n                    child = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=fd)\n                    if fp(os.fstat(child)) != pin:\n                        os.close(child)\n                        raise ValueError('recipe_tree_changed')\n                    files[path] = child\n                    size, digest, after = file_digest(child, overall_deadline)\n                    if after != pin:\n                        raise ValueError('recipe_tree_changed')\n                    rows[path] = {'type': 'file', 'generation': pin, 'size': size, 'sha256': digest, 'mode': stat.S_IMODE(info.st_mode)}\n                else:\n                    raise ValueError('recipe_tree_shape')\n            if fp(os.fstat(fd)) != before:\n                raise ValueError('recipe_tree_changed')\n        held = {'root': root, 'chain': chain, 'leaf': leaf, 'rows': rows, 'directories': directories, 'files': files}\n        recipe_generation_close(held)\n        if hold:\n            transferred = True\n            return held\n        return rows\n    finally:\n        if not transferred:\n            for fd in (*files.values(), *directories.values()):\n                os.close(fd)\n            close_parents(chain)\ndef recipe_generation_close(held):\n    guard_parents(held['chain'])\n    rows = held['rows']\n    for path, row in rows.items():\n        if row['type'] == 'directory' and sorted(os.listdir(held['directories'][path])) != row['names']:\n            raise ValueError('recipe_tree_changed')\n    for path, row in rows.items():\n        fd = held['directories'][path] if row['type'] == 'directory' else held['files'][path]\n        if path == '.':\n            named = os.stat(held['root'], follow_symlinks=False)\n        else:\n            parent, _, name = path.rpartition('/')\n            named = os.stat(name, dir_fd=held['directories'][parent or '.'], follow_symlinks=False)\n        if fp(os.fstat(fd)) != row['generation'] or fp(named) != row['generation']:\n            raise ValueError('recipe_tree_changed')\n    guard_parents(held['chain'])\n"
