METADATA_SOURCE = "def metadata_result(value, expected_stdout):\n    if type(value.returncode) is not int or value.returncode != 0 or type(value.stdout) is not str or value.stdout != expected_stdout or type(value.stderr) is not str or value.stderr != '':\n        raise ValueError('producer_strict_gate_failed')\n\ndef metadata_journal_file(name):\n    if not re.fullmatch('(terminal-proof|product-image-inventory|product-image-contract)\\\\.json(?:\\\\.manifest\\\\.json|\\\\.part-[0-9]{1,3})?', name):\n        raise ValueError('metadata_journal_changed')\n    fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=metadata_audit_fd)\n    metadata_journal_holds.append((name, fd, fp(os.fstat(fd))))\n    before = os.fstat(fd)\n    if not stat.S_ISREG(before.st_mode) or stat.S_IMODE(before.st_mode) != 384 or before.st_uid != 1000 or (before.st_gid != 1000) or (before.st_nlink != 1) or (not 0 < before.st_size <= 4096):\n        raise ValueError('metadata_journal_changed')\n    raw = os.pread(fd, 4097, 0)\n    if len(raw) != before.st_size or fp(before) != fp(os.fstat(fd)) or fp(before) != fp(os.stat(name, dir_fd=metadata_audit_fd, follow_symlinks=False)):\n        raise ValueError('metadata_journal_changed')\n    return raw\n\ndef metadata_journal(name):\n    if name == 'product-image-contract.json':\n        return metadata_journal_file(name)\n    manifest = json.loads(metadata_journal_file(name + '.manifest.json'))\n    if type(manifest) is not dict or set(manifest) != {'bytes', 'sha256', 'partBytes', 'partCount'} or any((type(manifest[x]) is not int for x in ('bytes', 'partBytes', 'partCount'))) or (manifest['partBytes'] != 4096) or (not 0 < manifest['bytes'] <= 1048576) or (manifest['partCount'] != (manifest['bytes'] + 4095) // 4096) or (type(manifest['sha256']) is not str) or (not re.fullmatch('[0-9a-f]{64}', manifest['sha256'])):\n        raise ValueError('metadata_journal_changed')\n    raw = b''.join((metadata_journal_file(name + '.part-' + str(i)) for i in range(manifest['partCount'])))\n    if len(raw) != manifest['bytes'] or hashlib.sha256(raw).hexdigest() != manifest['sha256']:\n        raise ValueError('metadata_journal_changed')\n    return raw\n\ndef metadata_journal_close():\n    if metadata_audit_fd is None:\n        return\n    guard_parents(metadata_chain)\n    if fp(os.fstat(metadata_audit_fd)) != metadata_audit_pin or fp(os.stat(METADATA_PARENT / 'audit', follow_symlinks=False)) != metadata_audit_pin:\n        raise ValueError('metadata_journal_changed')\n    for name, fd, pin in metadata_journal_holds:\n        if fp(os.fstat(fd)) != pin or fp(os.stat(name, dir_fd=metadata_audit_fd, follow_symlinks=False)) != pin:\n            raise ValueError('metadata_journal_changed')\n    guard_parents(metadata_chain)\n\ndef validate_role(command, kwargs):\n    if type(role_index) is not int or role_index not in (0, 1) or type(command) is not list or (command != [str(METADATA_IMAGE / 'bin/vpn-control'), ('--version', '--help')[role_index]]) or (kwargs != {'check': False, 'capture_output': True, 'text': True, 'timeout': 30}):\n        raise ValueError('producer_command_refused')\n    return ('product-version', 'product-help')[role_index]\n\ndef generated_image_guard():\n    if product_output_hold is not None:\n        recipe_copy_origin_facts(product_output_hold, metadata_output_origin)\n        recipe_catalogue_close(product_output_hold)\n    producer_guards()\n    generation_tree_closure(final_tree, min(overall_deadline, time.monotonic() + 30))\n    if product_output_hold is not None:\n        recipe_generation_only_close(product_output_hold)\n    metadata_journal_close()\n    held_guard()\n    archive_generation_closure()\n\ndef run_hello_gate():\n    global build_home, build_tmp, build_root, CHILD_ENV, producer_pass, audit_fd, audit_identity, product_config, product_output_hold, generated_image, metadata_audit_fd, metadata_audit_pin, metadata_chain, metadata_output_origin, product_fd_admission\n    producer_guards()\n    product_fd_admission = recipe_admit_fds()\n    for name in ('home', 'tmp', 'xdg-config', 'xdg-cache', 'xdg-data', 'xdg-state', 'audit'):\n        os.mkdir(name, 448, dir_fd=result_fd)\n    audit_fd = os.open('audit', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=result_fd)\n    info = os.fstat(audit_fd)\n    audit_identity = fp(info)[:2] + fp(info)[5:8]\n    producer_audit_guard()\n    build_root = result_dir\n    build_home = result_dir / 'home'\n    build_tmp = result_dir / 'tmp'\n    CHILD_ENV = {'HOME': str(build_home), 'TMPDIR': str(build_tmp), 'XDG_CONFIG_HOME': str(result_dir / 'xdg-config'), 'XDG_CACHE_HOME': str(result_dir / 'xdg-cache'), 'XDG_DATA_HOME': str(result_dir / 'xdg-data'), 'XDG_STATE_HOME': str(result_dir / 'xdg-state'), 'PATH': '/usr/bin:/bin', 'LANG': 'C.UTF-8', 'LC_ALL': 'C.UTF-8'}\n    metadata_chain, _ = parent_fds(METADATA_PARENT / 'audit')\n    metadata_audit_fd = os.open('audit', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=metadata_chain[-1]['fd'])\n    metadata_audit_pin = fp(os.fstat(metadata_audit_fd))\n    if stat.S_IMODE(metadata_audit_pin[5]) != 448 or metadata_audit_pin[6:8] != [1000, 1000]:\n        raise ValueError('metadata_journal_changed')\n    saved = metadata_journal('terminal-proof.json')\n    if saved != METADATA_TERMINAL_RAW or hashlib.sha256(saved + b'\\n').hexdigest() != METADATA_TERMINAL_SHA:\n        raise ValueError('metadata_journal_changed')\n    contract = json.loads(metadata_journal('product-image-contract.json'))\n    metadata_output_origin = json.loads(metadata_journal('product-image-inventory.json'))\n    product_output_hold = recipe_walk(METADATA_IMAGE, True)\n    recipe_copy_origin_facts(product_output_hold, metadata_output_origin)\n    source_fds = {path: item[2] for path, item in zip(pre, held)}\n    cfgfd = source_fds['opt/vpn-control/lib/app/vpn-control.cfg']\n    product_config = os.pread(cfgfd, 8192, 0)\n    recipe_config(product_config)\n    generated_image = recipe_output_contract(product_output_hold, GETTER['manifest']['files'], product_config, GETTER['manifest']['directories'])\n    expected = dict(contract)\n    expected.pop('fdAdmission', None)\n    if generated_image != expected:\n        raise ValueError('metadata_journal_changed')\n    generated_image_guard()\n    write_record(audit_fd, 'metadata-source-image.json', json.dumps({'sourceCorrelationId': METADATA_SOURCE_CORRELATION, 'terminalSha256': METADATA_TERMINAL_SHA, 'inventory': metadata_output_origin, 'contract': contract}, sort_keys=True, separators=(',', ':')).encode())\n    os.fsync(audit_fd)\n    generated_image_guard()\n    write_record(audit_fd, 'metadata-dispatch-fence.json', json.dumps({'correlationId': CORRELATION, 'roles': ['product-version', 'product-help'], 'replayAllowed': False}, sort_keys=True).encode())\n    os.fsync(audit_fd)\n    for flag, expected_stdout in (('--version', '2.2.2\\n'), ('--help', METADATA_HELP)):\n        value = fixed_runner([str(METADATA_IMAGE / 'bin/vpn-control'), flag], check=False, capture_output=True, text=True, timeout=30)\n        metadata_result(value, expected_stdout)\n        generated_image_guard()\n    if role_index != 2:\n        raise ValueError('producer_strict_gate_failed')\n    producer_pass = True\n"
